"use client";
import React, { useEffect } from 'react';
import { User } from 'lucide-react';

// Data members - sesuaikan dengan data tim Anda
const members = [
  {
    name: 'k.eii',
    description: 'killing AI with AI',
    tags: ['founder', 'for', 'ai/ml'],
    avatar: '/img/members/keii.jpg',
    blog: true
  },
  {
    name: 'itoid',
    description: 'idle and mmorpg games enjoyer',
    tags: ['founder', 'pwn', 'rev'],
    avatar: '/img/members/itoid.jpg',
    blog: true
  },
  {
    name: 'msfjr',
    description: '25k++ professional yapper',
    tags: ['pwn', 'rev'],
    avatar: '/img/members/msfjr.jpg',
    blog: false
  },
  {
    name: 'Darmodarr',
    description: 'just broke up with Mizuhara Chizuru, finding real one now',
    tags: ['for', 'blockchain'],
    avatar: '/img/members/darmodarr.jpg',
    blog: false
  },
  {
    name: 'FLaB',
    description: 'Web exploitation specialist',
    tags: ['web', 'for'],
    avatar: '/img/members/flab.jpg',
    blog: false
  },
  {
    name: 'yeLLow',
    description: 'Crypto and reverse engineering',
    tags: ['crypto', 'rev'],
    avatar: '/img/members/yellow.jpg',
    blog: true
  }
];

export default function MembersPage() {
      // Update title bar saat component dimuat
        useEffect(() => {
        document.title = 'Members | CCUG';
        }, []);
  return (
    <div className="min-h-screen ccug-bg text-white">

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {/* Breadcrumb */}
        <div className="mb-8">
          <p className="text-ccug-gray text-sm">
            <a href="/" className="hover:text-white transition">Home</a>
            <span className="mx-2">»</span>
            <span className="text-white">Members</span>
          </p>
        </div>

        {/* Page Title */}
        <div className="mb-12">
          <h2 className="text-4xl font-bold mb-4">Members</h2>
          <div className="border-b border-ccug-purple w-full"></div>
        </div>

        {/* Members Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {members.map((member, index) => (
            <div
              key={index}
              className="border-2 border-ccug-purple/50 rounded-lg p-6 bg-ccug-dark/50 hover:border-ccug-gray transition-colors"
            >
              <div className="flex items-start gap-4">
                {/* Avatar */}
                <div className="flex-shrink-0">
                  <div className="w-16 h-16 rounded-full bg-ccug-gray/20 flex items-center justify-center overflow-hidden">
                    {member.avatar ? (
                      <img 
                        src={member.avatar} 
                        alt={member.name}
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <User className="w-8 h-8 text-ccug-gray" />
                    )}
                  </div>
                </div>

                {/* Member Info */}
                <div className="flex-1">
                  <h3 className="text-xl font-bold mb-2 font-mono">{member.name}</h3>
                  <p className="text-ccug-gray text-sm mb-4">{member.description}</p>
                  
                  {/* Tags */}
                  <div className="flex flex-wrap gap-2 mb-3">
                    {member.tags.map((tag, tagIndex) => (
                      <span
                        key={tagIndex}
                        className={`px-3 py-1 rounded text-xs font-medium ${
                          tag === 'founder'
                            ? 'bg-red-500/20 text-red-300 border border-red-500/50'
                            : tag === 'pwn'
                            ? 'bg-orange-500/20 text-orange-300 border border-orange-500/50'
                            : tag === 'rev'
                            ? 'bg-yellow-500/20 text-yellow-300 border border-yellow-500/50'
                            : tag === 'for'
                            ? 'bg-blue-500/20 text-blue-300 border border-blue-500/50'
                            : tag === 'blockchain'
                            ? 'bg-teal-500/20 text-teal-300 border border-teal-500/50'
                            : tag === 'ai/ml'
                            ? 'bg-purple-500/20 text-purple-300 border border-purple-500/50'
                            : tag === 'web'
                            ? 'bg-green-500/20 text-green-300 border border-green-500/50'
                            : tag === 'crypto'
                            ? 'bg-pink-500/20 text-pink-300 border border-pink-500/50'
                            : 'bg-gray-500/20 text-gray-300 border border-gray-500/50'
                        }`}
                      >
                        {tag}
                      </span>
                    ))}
                  </div>

                  {/* Blog Badge */}
                  {member.blog && (
                    <div className="flex items-center gap-2">
                      <span className="w-2 h-2 bg-green-400 rounded-full"></span>
                      <span className="text-xs text-green-400 font-mono">Blog</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}